@Service
class NoteService {
    private final Map<Long, String> notes = new ConcurrentHashMap<>();
    private final AtomicLong ids = new AtomicLong();
    Map<Long, String> findAll() { return Map.copyOf(notes); }
    Optional<String> findById(long id) { return Optional.ofNullable(notes.get(id)); }
    long create(String text) {
        long id = ids.incrementAndGet(); notes.put(id, text); return id;
    }
    boolean delete(long id) { return notes.remove(id) != null; }
}
@RestController
@RequestMapping("/api/notes")
class NoteController {
    private final NoteService service;
    NoteController(NoteService service) { this.service = service; }
    @GetMapping Map<Long, String> all() { return service.findAll(); }
    @GetMapping("/{id}") String one(@PathVariable long id) {
        return service.findById(id).orElseThrow();
    }
    @PostMapping Map<String, Long> create(@RequestBody Map<String, String> body) {
        return Map.of("id", service.create(body.getOrDefault("text", "")));
    }
    @DeleteMapping("/{id}") void delete(@PathVariable long id) {
        if (!service.delete(id)) throw new NoSuchElementException("Note not found");
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final AtomicLong ids = new AtomicLong();
    record Product(long id, String name) {}
    @PostMapping
    public ResponseEntity<Product> create(@RequestBody Product request) {
        Product saved = new Product(ids.incrementAndGet(), request.name());
        URI location = URI.create("/api/products/" + saved.id());
        return ResponseEntity.created(location).body(saved);
    }
}

@RestControllerAdvice
public class ApiExceptionHandler {
    record ApiError(String code, String message) {}
    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ApiError> notFound(ResourceNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(new ApiError("NOT_FOUND", ex.getMessage()));
    }
}
class ResourceNotFoundException extends RuntimeException {
    ResourceNotFoundException(String message) { super(message); }
}

