@Entity
public class Product {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String name;
    protected Product() {}
    public Product(String name) { this.name = name; }
    public Long getId() { return id; }
    public String getName() { return name; }
}
public interface ProductRepository extends JpaRepository<Product, Long> {
    List<Product> findByNameContainingIgnoreCase(String name);
}

@Service
public class OrderService {
    private final OrderRepository orders;
    public OrderService(OrderRepository orders) { this.orders = orders; }

    @Transactional
    public void markPaid(Long id) {
        Order order = orders.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException("Order not found"));
        order.setStatus("PAID");
        // JPA dirty checking persists the managed entity at commit.
    }
}

@Service
public class ProductQueryService {
    private final ProductRepository repository;
    public ProductQueryService(ProductRepository repository) { this.repository = repository; }

    public Page<Product> findProducts(int page, int size) {
        if (page < 0 || size < 1 || size > 100)
            throw new IllegalArgumentException("Invalid page or size");
        Pageable pageable = PageRequest.of(page, size, Sort.by("name").ascending());
        return repository.findAll(pageable);
    }
}

